mapper.update:
UPDATE video_upload_parts
SET size_bytes = #{sizeBytes}
WHERE upload_id = #{uploadId} AND part_number = #{partNumber}

UPDATE video_upload_sessions
SET status = 1
WHERE upload_id = #{uploadId} AND status = 0 AND expires_at > #{now}

UPDATE video_upload_sessions
SET status = 2, completed_media_id = #{mediaId}
WHERE upload_id = #{uploadId} AND status = 1

UPDATE video_upload_sessions
SET status = 3
WHERE upload_id = #{uploadId} AND status = 0 AND expires_at <= #{now}

mapper.select:
SELECT 
FROM video_upload_sessions
WHERE status IN (0, 3) AND expires_at <= #{now}
ORDER BY expires_at ASC
LIMIT #{limit}
